Matching Ayahs
- = Alif, Lām, Meem. 2:1; 3:1; 29:1; 30:1; 31:1; 32:1
- = Ata janë në rrugë të drejtë nga Zoti i tyre, dhe ata janë të suksesshmit. 2:5; 31:5
- = O bij të Israilit, kujtoni dhuntinë Time që ju dhurova dhe se Unë ju lartësova mbi popujt (e tjerë). 2:47; 2:122
- = Ai ishte një popull që ka kaluar. Atij i takon ajo që fitoi, dhe juve ju takon ajo që fitoni. Dhe ju nuk do të pyeteni për atë që ata punonin. 2:134; 2:141
- = Aty do të jenë përgjithmonë. Dënimi nuk do t'u lehtësohet atyre, e as nuk do të shtyhen. 2:162; 3:88
- = Përveç atyre që pendohen pas kësaj dhe përmirësohen. Vërtet, All-llahu është Falës dhe Mëshirues. 3:89; 24:5
- = E ata që nuk besuan dhe i mohuan argumentet Tona – ata janë banorët e Xhehennemit. 5:10; 5:86
- = Dhe nuk u vjen atyre ndonjë argument nga argumentet e Zotit të tyre, pa e kthyer shpinën atij. 6:4; 36:46
- = Dhe para teje u tallën me të dërguarit, por ata që tallnin i përfshiu ajo me çka talleshin. 6:10; 21:41
- = Thuaj: "Unë, nëse kundërshtoj Zotin tim, kam frikë dënimin e një Dite të madhe." 6:15; 39:13
