- Kush nuk gjykon me atë që zbriti Zoti, ata janë. (وَمَن لَّمْ يَحْكُم بِمَا أَنزَلَ اللَّهُ فَأُولَئِكَ هُمُ) 5:44; 5:45; 5:47
- Krijoi qiejt dhe tokën dhe çfarë është ndërmjet tyre në gjashtë ditë. (خَلَقَ السَّمَاوَاتِ وَالْأَرْضَ وَمَا بَيْنَهُمَا فِي سِتَّةِ أَيَّامٍ) 25:59; 32:4; 50:38
- Zoti është i mirë ndaj njerëzve, por shumica. (إِنَّ اللَّهَ لَذُو فَضْلٍ عَلَى النَّاسِ وَلَكِنَّ أَكْثَرَ) 2:243; 10:60; 40:61
- Dhe Zoti nuk ishte për t'i padrejtësuar, por ata e padrejtësonin veten. (فَمَا كَانَ اللَّهُ لِيَظْلِمَهُمْ وَلَكِن كَانُوا أَنفُسَهُمْ يَظْلِمُونَ) 9:70; 29:40; 30:9
- Mbulon të këqijat tuaja dhe do t'ju futë në xhenete nëpër të cilat rrjedhin lumenj. (عَنكُمْ سَيِّئَاتِكُمْ وَلَأُدْخِلَنَّكُمْ جَنَّاتٍ تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ) 5:12; 64:9; 66:8
- Ua ndaloi të ngordhurën, gjakun, mishin e derrit dhe atë që u përkushtua. (حَرَّمَ عَلَيْكُمُ الْمَيْتَةَ وَالدَّمَ وَلَحْمَ الْخِنزِيرِ وَمَا أُهِلَّ) 2:173; 5:3; 16:115
- Unë kam frikë, nëse kundërshtoj Zotin tim, nga dënimi i një Dite të Madhe. (إِنِّي أَخَافُ إِنْ عَصَيْتُ رَبِّي عَذَابَ يَوْمٍ عَظِيمٍ) 6:15; 10:15; 39:13
- Përveç pasi u erdhi dituria, nga zilia mes tyre. (إِلَّا مِن بَعْدِ مَا جَاءَهُمُ الْعِلْمُ بَغْيًا بَيْنَهُمْ) 3:19; 42:14; 45:17
- E falën namazin dhe dhanë nga ajo që i furnizuam, fshehtas dhe haptas. (وَأَقَامُوا الصَّلَاةَ وَأَنفَقُوا مِمَّا رَزَقْنَاهُمْ سِرًّا وَعَلَانِيَةً) 13:22; 14:31; 35:29
- Në vend të Zotit, atë që nuk na sjell dobi as dëm. (مِن دُونِ اللَّهِ مَا لَا يَنفَعُنَا وَلَا يَضُرُّنَا) 6:71; 10:106; 25:55
- Besojnë në atë që të zbriti ty dhe në atë që u zbrit para teje. (يُؤْمِنُونَ بِمَا أُنزِلَ إِلَيْكَ وَمَا أُنزِلَ مِن قَبْلِكَ) 2:4; 4:60; 4:162
- A nuk e pe se Zoti zbriti nga qielli ujë. (أَلَمْ تَرَ أَنَّ اللَّهَ أَنزَلَ مِنَ السَّمَاءِ مَاءً) 22:63; 35:27; 39:21
- Kur vendos një çështje, Ai i thotë: Bëhu, dhe bëhet. (قَضَى أَمْرًا فَإِنَّمَا يَقُولُ لَهُ كُن فَيَكُونُ) 3:47; 19:35; 40:68
- Dhe te Medjeni, vëllain e tyre Shuajbin, tha: O populli im, adhuroni Zotin. (وَإِلَى مَدْيَنَ أَخَاهُمْ شُعَيْبًا قَالَ يَاقَوْمِ اعْبُدُوا اللَّهَ) 7:85; 11:84; 29:36
- Kjo është nga lajmet e padukshme që ta shpallim ty, dhe ti nuk ishe. (ذَلِكَ مِنْ أَنْبَاءِ الْغَيْبِ نُوحِيهِ إِلَيْكَ وَمَا كُنتَ) 3:44; 11:49; 12:102
- Dhe kur të vijë afati i tyre, nuk e vonojnë asnjë çast, as nuk e paraprijnë. (فَإِذَا جَاءَ أَجَلُهُمْ لَا يَسْتَأْخِرُونَ سَاعَةً وَلَا يَسْتَقْدِمُونَ) 7:34; 10:49; 16:61
- E mos ndiqni hapat e djallit, se ai është armik i hapur për ju. (وَلَا تَتَّبِعُوا خُطُوَاتِ الشَّيْطَانِ إِنَّهُ لَكُمْ عَدُوٌّ مُّبِينٌ) 2:168; 2:208; 6:142
- Ka nga njerëzit që polemizojnë për Zotin pa dituri. (وَمِنَ النَّاسِ مَن يُجَادِلُ فِي اللَّهِ بِغَيْرِ عِلْمٍ) 22:3; 22:8; 31:20
- Zoti ia jep kujt do, dhe Zoti është i bollshëm në mirësi. (اللَّهِ يُؤْتِيهِ مَن يَشَاءُ وَاللَّهُ ذُو الْفَضْلِ الْعَظِيمِ) 57:21; 57:29; 62:4
- Secilit njeri do t'i shpërblehet ajo që fitoi, dhe atyre nuk u bëhet e padrejtë. (تُوَفَّى كُلُّ نَفْسٍ مَّا كَسَبَتْ وَهُمْ لَا يُظْلَمُونَ) 2:281; 3:25; 3:161
- E mos e mbytni jetën që Zoti e ka ndaluar, përveç me të drejtë. (وَلَا تَقْتُلُوا النَّفْسَ الَّتِي حَرَّمَ اللَّهُ إِلَّا بِالْحَقِّ) 6:151; 17:33; 25:68
- Kur vendos një çështje, Ai i thotë: Bëhu. (إِذَا قَضَى أَمْرًا فَإِنَّمَا يَقُولُ لَهُ كُن) 3:47; 19:35; 40:68
- Hyni në portat e Xhehennemit, ku do të jeni përgjithmonë; sa vendbanim i keq për arrogantët. (فَادْخُلُوا أَبْوَابَ جَهَنَّمَ خَالِدِينَ فِيهَا فَلَبِئْسَ مَثْوَى الْمُتَكَبِّرِينَ) 16:29; 39:72; 40:76
- A nuk i pe ata që u dhanë një pjesë nga Libri. (أَلَمْ تَرَ إِلَى الَّذِينَ أُوتُوا نَصِيبًا مِّنَ الْكِتَابِ) 3:23; 4:44; 4:51
- Ata kanë xhenete nëpër të cilat rrjedhin lumenj, ku do të jenë përgjithmonë. (لَهُمْ جَنَّاتٌ تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا) 3:198; 5:119; 9:89
- O populli im, veproni sipas mundësisë tuaj, se unë do të veproj, e shpejt do ta dini. (يَاقَوْمِ اعْمَلُوا عَلَى مَكَانَتِكُمْ إِنِّي عَامِلٌ فَسَوْفَ تَعْلَمُونَ) 6:135; 11:93; 39:39
- Zotin dhe të dërguarin e Tij, atij i takon zjarri i Xhehennemit, ku do të jetë përgjithmonë. (اللَّهَ وَرَسُولَهُ فَأَنَّ لَهُ نَارَ جَهَنَّمَ خَالِدًا فِيهَا) 9:63; 72:23
- Në zemrat e tyre kemi vënë mbulesa që ta kuptojnë, dhe në veshët e tyre rëndim. (عَلَى قُلُوبِهِمْ أَكِنَّةً أَن يَفْقَهُوهُ وَفِي آذَانِهِمْ وَقْرًا) 17:46; 18:57
- Në një fshat me qortues, përveç se të pasurit e tij thanë: Ne. (فِي قَرْيَةٍ مِّن نَّذِيرٍ إِلَّا قَالَ مُتْرَفُوهَا إِنَّا) 34:34; 43:23
- Thanë: Thirre Zotit tënd për ne të na shpjegojë se çfarë është. (قَالُوا ادْعُ لَنَا رَبَّكَ يُبَيِّن لَّنَا مَا هِيَ) 2:68; 2:70
- Do të thonë: Zoti. Thuaj: Falenderimi i qoftë Zotit, por shumica prej tyre nuk. (لَيَقُولُنَّ اللَّهُ قُلِ الْحَمْدُ لِلَّهِ بَلْ أَكْثَرُهُمْ لَا) 29:63; 31:25
- Dhe përgjigja e popullit të tij nuk ishte veçse të thoshin: Dëboni ata. (وَمَا كَانَ جَوَابَ قَوْمِهِ إِلَّا أَن قَالُوا أَخْرِجُوهُم) 7:82; 27:56
- Nën të lumenj, ku do të jenë përgjithmonë; ajo është shpëtimi i madh. (تَحْتَهَا الْأَنْهَارُ خَالِدِينَ فِيهَا أَبَدًا ذَلِكَ الْفَوْزُ الْعَظِيمُ) 9:100; 64:9
- Ata janë në udhëzim nga Zoti i tyre, dhe ata janë të shpëtuarit. (أُولَئِكَ عَلَى هُدًى مِّن رَّبِّهِمْ وَأُولَئِكَ هُمُ الْمُفْلِحُونَ) 2:5; 31:5
- Atë që do ta godasë dënimi që e poshtëron dhe do ta përfshijë dënimi i përhershëm. (مَن يَأْتِيهِ عَذَابٌ يُخْزِيهِ وَيَحِلُّ عَلَيْهِ عَذَابٌ مُّقِيمٌ) 11:39; 39:40
- Ecni nëpër tokë dhe shikoni si ishte përfundimi i përgënjeshtruesve. (فَسِيرُوا فِي الْأَرْضِ فَانظُرُوا كَيْفَ كَانَ عَاقِبَةُ الْمُكَذِّبِينَ) 3:137; 16:36
- Nuk e dëshirojnë atë kurrë për shkak të asaj që duart e tyre kanë çuar përpara, dhe Zoti i di mizorët. (يَتَمَنَّوْهُ أَبَدًا بِمَا قَدَّمَتْ أَيْدِيهِمْ وَاللَّهُ عَلِيمٌ بِالظَّالِمِينَ) 2:95; 62:7
- Ai di më mirë kush humb nga rruga e Tij, dhe Ai di më mirë. (هُوَ أَعْلَمُ بِمَن ضَلَّ عَن سَبِيلِهِ وَهُوَ أَعْلَمُ) 53:30; 68:7
- Zoti është Zoti im dhe Zoti juaj, prandaj adhuroni Atë; kjo është rrugë e drejtë. (إِنَّ اللَّهَ رَبِّي وَرَبُّكُمْ فَاعْبُدُوهُ هَذَا صِرَاطٌ مُّسْتَقِيمٌ) 3:51; 19:36
- I mirë ndaj njerëzve, por shumica prej tyre nuk janë mirënjohës. (لَذُو فَضْلٍ عَلَى النَّاسِ وَلَكِنَّ أَكْثَرَهُمْ لَا يَشْكُرُونَ) 10:60; 27:73
- Qiejt dhe tokën dhe çfarë është ndërmjet tyre, vetëm me të vërtetë dhe një afat të caktuar. (السَّمَاوَاتِ وَالْأَرْضَ وَمَا بَيْنَهُمَا إِلَّا بِالْحَقِّ وَأَجَلٍ مُّسَمًّى) 30:8; 46:3
- Lëri ata të zhyten dhe të luajnë derisa të përballen me ditën që u premtohet. (فَذَرْهُمْ يَخُوضُوا وَيَلْعَبُوا حَتَّى يُلَاقُوا يَوْمَهُمُ الَّذِي يُوعَدُونَ) 43:83; 70:42
- Kur takojnë ata që besuan, thonë: Besuam, e kur mbesin vetëm. (وَإِذَا لَقُوا الَّذِينَ آمَنُوا قَالُوا آمَنَّا وَإِذَا خَلَوْا) 2:14; 2:76
- E zbatojnë Tevratin dhe Inxhilin dhe atë që u zbrit prej Zotit të tyre. (أَقَامُوا التَّوْرَاةَ وَالْإِنجِيلَ وَمَا أُنزِلَ إِلَيْهِم مِّن رَّبِّهِمْ) 5:66; 5:68
- E di çfarë është përpara tyre dhe çfarë prapa tyre, dhe ata nuk e përfshijnë. (يَعْلَمُ مَا بَيْنَ أَيْدِيهِمْ وَمَا خَلْفَهُمْ وَلَا يُحِيطُونَ) 2:255; 20:110
- Ai është që krijoi qiejt dhe tokën në gjashtë ditë. (وَهُوَ الَّذِي خَلَقَ السَّمَاوَاتِ وَالْأَرْضَ فِي سِتَّةِ أَيَّامٍ) 11:7; 57:4
- Në këtë ka një shenjë për ju, nëse jeni besimtarë. (إِنَّ فِي ذَلِكَ لَآيَةً لَّكُمْ إِن كُنتُم مُّؤْمِنِينَ) 2:248; 3:49
- Çfarë i pengoi njerëzit të besojnë kur u erdhi udhëzimi. (وَمَا مَنَعَ النَّاسَ أَن يُؤْمِنُوا إِذْ جَاءَهُمُ الْهُدَى) 17:94; 18:55
- Dhe i vunë Zotit shokë, për të humbur nga rruga e Tij. Thuaj: Kënaquni. (وَجَعَلُوا لِلَّهِ أَندَادًا لِّيُضِلُّوا عَن سَبِيلِهِ قُلْ تَمَتَّعُوا) 14:30; 39:8
- Dhe u çuditën që u erdhi një qortues prej tyre, dhe jobesimtarët thanë: Ky është. (وَعَجِبُوا أَن جَاءَهُم مُّنذِرٌ مِّنْهُمْ وَقَالَ الْكَافِرُونَ هَذَا) 38:4; 50:2
- Zoti yt di më mirë kush humb nga rruga e Tij. (إِنَّ رَبَّكَ هُوَ أَعْلَمُ بِمَن ضَلَّ عَن سَبِيلِهِ) 53:30; 68:7
- Ai që e shpenzon pasurinë e tij për sy e faqe të njerëzve dhe nuk beson në Zotin. (كَالَّذِي يُنفِقُ مَالَهُ رِئَاءَ النَّاسِ وَلَا يُؤْمِنُ بِاللَّهِ) 2:264; 4:38
- Shpenzoni nga ajo që ju furnizuam, para se të vijë. (أَنفِقُوا مِمَّا رَزَقْنَاكُم مِّن قَبْلِ أَن يَأْتِيَ) 2:254; 63:10
- Nënshtroi për ju çfarë ka në qiej dhe çfarë ka në tokë. (سَخَّرَ لَكُم مَّا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ) 31:20; 45:13
- Ne jemi në dyshim për atë që na ftoni, shqetësues. (وَإِنَّنَا لَفِي شَكٍّ مِّمَّا تَدْعُونَا إِلَيْهِ مُرِيبٍ) 11:62; 14:9
- Zoti yt e zgjeron furnizimin për kë të do dhe e ngushton; Ai. (إِنَّ رَبَّكَ يَبْسُطُ الرِّزْقَ لِمَن يَشَاءُ وَيَقْدِرُ إِنَّهُ) 17:30; 34:36
- Zoti i qiejve dhe i tokës dhe çfarë është ndërmjet tyre, nëse jeni të bindur. (رَبُّ السَّمَاوَاتِ وَالْأَرْضِ وَمَا بَيْنَهُمَا إِن كُنتُم مُّوقِنِينَ) 26:24; 44:7
- Besuam në Zotin dhe në atë që na zbriti neve dhe atë që i zbriti. (آمَنَّا بِاللَّهِ وَمَا أُنزِلَ إِلَيْنَا وَمَا أُنزِلَ إِلَى) 2:136; 3:199
- Dhe ata që kishin bërë mizari i kapi ushtima, e u gjetën në shtëpitë e tyre të përmbysur. (وَأَخَذَ الَّذِينَ ظَلَمُوا الصَّيْحَةُ فَأَصْبَحُوا فِي دِيَارِهِمْ جَاثِمِينَ) 11:67; 11:94
- Nuk ka mëkat për ju në atë që ato bëjnë me veten e tyre. (فَلَا جُنَاحَ عَلَيْكُمْ فِيمَا فَعَلْنَ فِي أَنفُسِهِنَّ) 2:234; 2:240
- Zoti yt di më mirë kush humb nga rruga e Tij, dhe Ai. (رَبَّكَ هُوَ أَعْلَمُ بِمَن ضَلَّ عَن سَبِيلِهِ وَهُوَ) 53:30; 68:7
- Me shpirtin nga urdhri i Tij, kujt do nga robërit e Tij. (بِالرُّوحِ مِنْ أَمْرِهِ عَلَى مَن يَشَاءُ مِنْ عِبَادِهِ) 16:2; 40:15
- Dhe Isait, birit të Merjemit, i dhamë argumente të qarta dhe e fuqizuam me Shpirtin e Shenjtë. (وَآتَيْنَا عِيسَى ابْنَ مَرْيَمَ الْبَيِّنَاتِ وَأَيَّدْنَاهُ بِرُوحِ الْقُدُسِ) 2:87; 2:253
- Të gjykojë mes tyre në Ditën e Kijametit për atë që kishin. (لَيَحْكُمُ بَيْنَهُمْ يَوْمَ الْقِيَامَةِ فِيمَا كَانُوا فِيهِ) 16:124; 22:69
- Pjesën e sipërme të saj e bëmë të poshtme dhe mbi të reshëm gurë balte. (جَعَلْنَا عَالِيَهَا سَافِلَهَا وَأَمْطَرْنَا عَلَيْهَا حِجَارَةً مِّن سِجِّيلٍ) 11:82; 15:74
- Është njësoj për ta, i qortove apo nuk i qortove, nuk besojnë. (سَوَاءٌ عَلَيْهِمْ أَأَنذَرْتَهُمْ أَمْ لَمْ تُنذِرْهُمْ لَا يُؤْمِنُونَ) 2:6; 36:10
- Në vend të njerëzve, atëherë dëshironi vdekjen, nëse jeni të sinqertë. (مِّن دُونِ النَّاسِ فَتَمَنَّوُا الْمَوْتَ إِن كُنتُمْ صَادِقِينَ) 2:94; 62:6
- Zotin, ju nuk keni zot tjetër përveç Tij. A nuk i frikësoheni? (اللَّهَ مَا لَكُم مِّنْ إِلَهٍ غَيْرُهُ أَفَلَا تَتَّقُونَ) 23:23; 23:32
- Qoftë të të tregojmë një pjesë të asaj që u premtojmë, qoftë të të marrim, te Ne është kthimi. (وَإِمَّا نُرِيَنَّكَ بَعْضَ الَّذِي نَعِدُهُمْ أَوْ نَتَوَفَّيَنَّكَ فَإِلَيْنَا) 10:46; 40:77
- Thanë: A kur të kemi vdekur e të jemi bërë pluhur e eshtra, a do të ringjallemi? (قَالُوا أَإِذَا مِتْنَا وَكُنَّا تُرَابًا وَعِظَامًا أَإِنَّا لَمَبْعُوثُونَ) 23:82; 56:47
- Miri është në dorë të Zotit, Ai ia jep kujt do, dhe Zoti. (إِنَّ الْفَضْلَ بِيَدِ اللَّهِ يُؤْتِيهِ مَن يَشَاءُ وَاللَّهُ) 3:73; 57:29
- Tek Njohësi i të padukshmes dhe të dukshmes, e Ai do t'ju lajmërojë për atë që keni bërë. (إِلَى عَالِمِ الْغَيْبِ وَالشَّهَادَةِ فَيُنَبِّئُكُم بِمَا كُنتُمْ تَعْمَلُونَ) 9:105; 62:8
- O ju që besuat, kujtoni dhuntinë e Zotit ndaj jush, kur. (يَا أَيُّهَا الَّذِينَ آمَنُوا اذْكُرُوا نِعْمَتَ اللَّهِ عَلَيْكُمْ إِذْ) 5:11; 33:9
- Dhe nuk dërguam para teje, përveç burra që u shpallnim. (وَمَا أَرْسَلْنَا مِن قَبْلِكَ إِلَّا رِجَالًا نُّوحِي إِلَيْهِم) 12:109; 16:43
- I fal të këqijat e tij dhe e fut në xhenete nëpër të cilat rrjedhin lumenj. (يُكَفِّرْ عَنْهُ سَيِّئَاتِهِ وَيُدْخِلْهُ جَنَّاتٍ تَجْرِي مِن تَحْتِهَا) 64:9; 66:8
- I sëmurë ose në udhëtim, atëherë një numër ditësh të tjera. (مَّرِيضًا أَوْ عَلَى سَفَرٍ فَعِدَّةٌ مِّنْ أَيَّامٍ أُخَرَ) 2:184; 2:185
- Ata nuk ndjekin tjetër veç hamendjes dhe ata nuk bëjnë veçse gënjejnë. (إِن يَتَّبِعُونَ إِلَّا الظَّنَّ وَإِنْ هُمْ إِلَّا يَخْرُصُونَ) 6:116; 10:66
- Shembull i mirë për atë që shpreson në Zotin dhe Ditën e Fundit. (أُسْوَةٌ حَسَنَةٌ لِّمَن كَانَ يَرْجُو اللَّهَ وَالْيَوْمَ الْآخِرَ) 33:21; 60:6
- Ne nuk i krijuam qiejt dhe tokën dhe çfarë është ndërmjet tyre, përveç me të vërtetë. (وَمَا خَلَقْنَا السَّمَاوَاتِ وَالْأَرْضَ وَمَا بَيْنَهُمَا إِلَّا بِالْحَقِّ) 15:85; 46:3
- Futen dorën tënde në xhepin tënd, të dalë e bardhë pa të keq. (يَدَكَ فِي جَيْبِكَ تَخْرُجْ بَيْضَاءَ مِنْ غَيْرِ سُوءٍ) 27:12; 28:32
- Ai e veçon me mëshirën e Tij kë të do, dhe Zoti është i bollshëm në mirësi. (يَخْتَصُّ بِرَحْمَتِهِ مَن يَشَاءُ وَاللَّهُ ذُو الْفَضْلِ الْعَظِيمِ) 2:105; 3:74
- A nuk e di se Zotit i takon sundimi i qiejve dhe i tokës. (أَلَمْ تَعْلَمْ أَنَّ اللَّهَ لَهُ مُلْكُ السَّمَاوَاتِ وَالْأَرْضِ) 2:107; 5:40
- Çfarë të mira të dërgoni për veten tuaj, do ta gjeni te Zoti. (وَمَا تُقَدِّمُوا لِأَنفُسِكُم مِّنْ خَيْرٍ تَجِدُوهُ عِندَ اللَّهِ) 2:110; 73:20
- Dhe nga kudo që të dalësh, kthe fytyrën tënde nga Xhamia e Shenjtë. (وَمِنْ حَيْثُ خَرَجْتَ فَوَلِّ وَجْهَكَ شَطْرَ الْمَسْجِدِ الْحَرَامِ) 2:149; 2:150
- Ata që kaluan para jush, dhe për ligjin e Zotit nuk do të gjesh ndryshim. (خَلَوْا مِن قَبْلُ وَلَن تَجِدَ لِسُنَّةِ اللَّهِ تَبْدِيلًا) 33:62; 48:23
- Atij që i takon çfarë ka në qiej dhe çfarë ka në tokë. (الَّذِي لَهُ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ) 34:1; 42:53
- Dhe asnjë femër nuk mbart e nuk lind, përveçse me dijen e Tij. (وَمَا تَحْمِلُ مِنْ أُنثَى وَلَا تَضَعُ إِلَّا بِعِلْمِهِ) 35:11; 41:47
- Natën dhe nënshtroi diellin dhe hënën, secili rrjedh për një afat të caktuar. (اللَّيْلِ وَسَخَّرَ الشَّمْسَ وَالْقَمَرَ كُلٌّ يَجْرِي لِأَجَلٍ مُّسَمًّى) 35:13; 39:5
- Nën të rrjedhin lumenj, ku do të jenë përgjithmonë, dhe ai është shpërblimi. (تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا وَذَلِكَ جَزَاءُ) 5:85; 20:76
- Tha: Përkundrazi, vetë jua zbukuruan një çështje; durim i bukur. (قَالَ بَلْ سَوَّلَتْ لَكُمْ أَنفُسُكُمْ أَمْرًا فَصَبْرٌ جَمِيلٌ) 12:18; 12:83
- Çfarë ka në qiej dhe çfarë ka në tokë, dhe se Zoti. (مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ وَأَنَّ اللَّهَ) 5:97; 22:64
- Dhe nuk u vinte asnjë i dërguar, përveç se e tallnin. (وَمَا يَأْتِيهِم مِّن رَّسُولٍ إِلَّا كَانُوا بِهِ يَسْتَهْزِئُونَ) 15:11; 36:30
- Thanë: O Musa, ose të hedhësh ti, ose të jemi ne. (قَالُوا يَامُوسَى إِمَّا أَن تُلْقِيَ وَإِمَّا أَن نَّكُونَ) 7:115; 20:65
- Ai ju vdes dhe prej jush ka që kthehet në moshën më të ulët, për të. (يَتَوَفَّاكُمْ وَمِنكُم مَّن يُرَدُّ إِلَى أَرْذَلِ الْعُمُرِ لِكَيْ) 16:70; 22:5
- Ata kanë xhenete nëpër të cilat rrjedhin lumenj, ku do të jenë përgjithmonë. (رَبِّهِمْ جَنَّاتٌ تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا) 3:15; 3:136
- Dhe në zemrat e tyre vumë mbulesa që ta kuptojnë dhe në veshët e tyre rëndim. (وَجَعَلْنَا عَلَى قُلُوبِهِمْ أَكِنَّةً أَن يَفْقَهُوهُ وَفِي آذَانِهِمْ) 17:46; 18:57
- Premtimi i Zotit është i vërtetë, por shumica prej tyre nuk e dinë. (إِنَّ وَعْدَ اللَّهِ حَقٌّ وَلَكِنَّ أَكْثَرَهُمْ لَا يَعْلَمُونَ) 10:55; 28:13
- Kjo, sepse ata kundërshtuan Zotin dhe të dërguarin e Tij; e kush kundërshton Zotin. (ذَلِكَ بِأَنَّهُمْ شَاقُّوا اللَّهَ وَرَسُولَهُ وَمَن يُشَاقِقِ اللَّهَ) 8:13; 59:4
- Dhe Ditën kur i thërret e thotë: Ku janë shokët e Mi që i trinit? (وَيَوْمَ يُنَادِيهِمْ فَيَقُولُ أَيْنَ شُرَكَائِيَ الَّذِينَ كُنتُمْ تَزْعُمُونَ) 28:62; 28:74
- A nuk e panë se Zoti që krijoi qiejt dhe tokën. (أَوَلَمْ يَرَوْا أَنَّ اللَّهَ الَّذِي خَلَقَ السَّمَاوَاتِ وَالْأَرْضَ) 17:99; 46:33
- Me Atë që të krijoi nga pluhuri, pastaj nga pika, pastaj. (بِالَّذِي خَلَقَكَ مِن تُرَابٍ ثُمَّ مِن نُّطْفَةٍ ثُمَّ) 18:37; 40:67
- Do të thonin: Zoti ynë, pse nuk na dërgove një të dërguar, që të pasojmë argumentet e Tua. (لَقَالُوا رَبَّنَا لَوْلَا أَرْسَلْتَ إِلَيْنَا رَسُولًا فَنَتَّبِعَ آيَاتِكَ) 20:134; 28:47
- Pastaj te Zoti i tyre është kthimi, e Ai do t'i lajmërojë për atë që bënin. (ثُمَّ إِلَى رَبِّهِم مَّرْجِعُهُمْ فَيُنَبِّئُهُم بِمَا كَانُوا يَعْمَلُونَ) 6:108; 39:7
- Ata nuk kanë për këtë ndonjë dituri; ata nuk janë veçse. (مَّا لَهُم بِذَلِكَ مِنْ عِلْمٍ إِنْ هُمْ إِلَّا) 43:20; 45:24
- Ne i gjetëm prindërit tanë në një fe dhe ne jemi në gjurmët e tyre. (إِنَّا وَجَدْنَا آبَاءَنَا عَلَى أُمَّةٍ وَإِنَّا عَلَى آثَارِهِم) 43:22; 43:23
- Atyre që u është dhënë Libri, përveçse pasi u erdhi. (الَّذِينَ أُوتُوا الْكِتَابَ إِلَّا مِن بَعْدِ مَا جَاءَهُمُ) 3:19; 98:4
- Dhe kur Ibrahimi tha: Zoti im, bëje këtë qytet të sigurt. (وَإِذْ قَالَ إِبْرَاهِيمُ رَبِّ اجْعَلْ هَذَا بَلَدًا آمِنًا) 2:126; 14:35
- Dhe ju dha të dëgjuarit, të parit dhe zemrat; pak jeni mirënjohës. (وَجَعَلَ لَكُمُ السَّمْعَ وَالْأَبْصَارَ وَالْأَفْئِدَةَ قَلِيلًا مَّا تَشْكُرُونَ) 32:9; 67:23
- Ata që polemizojnë për shpalljet e Zotit pa ndonjë autoritet që u ka ardhur. (الَّذِينَ يُجَادِلُونَ فِي آيَاتِ اللَّهِ بِغَيْرِ سُلْطَانٍ أَتَاهُمْ) 40:35; 40:56
- Ndiqni fenë e Ibrahimit të drejtë, e ai nuk ishte nga politeistët. (فَاتَّبِعُوا مِلَّةَ إِبْرَاهِيمَ حَنِيفًا وَمَا كَانَ مِنَ الْمُشْرِكِينَ) 3:95; 16:123
- Dhe ju shpëtuam nga familja e Faraonit, që ju vërsulën dënimin më të keq. (وَإِذْ أَنجَيْنَاكُم مِّنْ آلِ فِرْعَوْنَ يَسُومُونَكُمْ سُوءَ الْعَذَابِ) 7:141; 14:6
- Ajo është feja e drejtë, por shumica e njerëzve nuk e dinë. (ذَلِكَ الدِّينُ الْقَيِّمُ وَلَكِنَّ أَكْثَرَ النَّاسِ لَا يَعْلَمُونَ) 12:40; 30:30
- A nuk e pe se Zoti nënshtroi për ju çfarë ka në. (أَلَمْ تَرَ أَنَّ اللَّهَ سَخَّرَ لَكُم مَّا فِي) 22:65; 31:20
- Jobesimtarët do të thonin: Kjo nuk është veçse magji e qartë. (لَقَالَ الَّذِينَ كَفَرُوا إِنْ هَذَا إِلَّا سِحْرٌ مُّبِينٌ) 6:7; 11:7
- Dhe kur u lexohen argumentet Tona të qarta, jobesimtarët thonë. (وَإِذَا تُتْلَى عَلَيْهِمْ آيَاتُنَا بَيِّنَاتٍ قَالَ الَّذِينَ كَفَرُوا) 19:73; 46:7
- Xhenete të Adnit, nëpër të cilat rrjedhin lumenj, ku do të jenë përgjithmonë. (جَنَّاتُ عَدْنٍ تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا) 20:76; 98:8
- Çfarë do, Zoti është mbi çdo gjë i fuqishëm. (مَا يَشَاءُ إِنَّ اللَّهَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ) 24:45; 35:1
- T'ju falë mëkatet tuaja dhe t'ju shtyjë deri në një afat të caktuar. (لِيَغْفِرَ لَكُم مِّن ذُنُوبِكُمْ وَيُؤَخِّرَكُمْ إِلَى أَجَلٍ مُّسَمًّى) 14:10; 71:4
- Doni të na ktheni nga ajo që adhuronin prindërit tanë. (تُرِيدُونَ أَن تَصُدُّونَا عَمَّا كَانَ يَعْبُدُ آبَاؤُنَا) 14:10; 34:43
- Kur Zoti yt u tha engjëjve: Unë do të krijoj një njeri nga. (وَإِذْ قَالَ رَبُّكَ لِلْمَلَائِكَةِ إِنِّي خَالِقٌ بَشَرًا مِّن) 15:28; 38:71
- Ai është që dërgon erërat si lajm i mirë para mëshirës së Tij. (وَهُوَ الَّذِي يُرْسِلُ الرِّيَاحَ بُشْرًا بَيْنَ يَدَيْ رَحْمَتِهِ) 7:57; 25:48
- Thuaj: Ecni nëpër tokë dhe shikoni si ishte përfundimi. (قُلْ سِيرُوا فِي الْأَرْضِ فَانظُرُوا كَيْفَ كَانَ عَاقِبَةُ) 27:69; 30:42
- Në krijimin e qiejve dhe të tokës dhe në ndryshimin e natës dhe ditës. (إِنَّ فِي خَلْقِ السَّمَاوَاتِ وَالْأَرْضِ وَاخْتِلَافِ اللَّيْلِ وَالنَّهَارِ) 2:164; 3:190
- Kush është ai që i jep Zotit hua të mirë, e Ai ia shumëfishon. (مَّن ذَا الَّذِي يُقْرِضُ اللَّهَ قَرْضًا حَسَنًا فَيُضَاعِفَهُ) 2:245; 57:11
- Gjykoni mes tyre me atë që zbriti Zoti dhe mos ndiqni dëshirat e tyre. (فَاحْكُم بَيْنَهُم بِمَا أَنزَلَ اللَّهُ وَلَا تَتَّبِعْ أَهْوَاءَهُمْ) 5:48; 5:49
- A presin tjetër veçse t'u vijnë engjëjt ose të vijë. (هَلْ يَنظُرُونَ إِلَّا أَن تَأْتِيَهُمُ الْمَلَائِكَةُ أَوْ يَأْتِيَ) 6:158; 16:33
- Ata që shpifin gënjeshtra për Zotin, nuk do të shpëtojnë. (إِنَّ الَّذِينَ يَفْتَرُونَ عَلَى اللَّهِ الْكَذِبَ لَا يُفْلِحُونَ) 10:69; 16:116
- Si zakoni i familjes së Faraonit dhe i atyre para tyre, përgënjeshtruan shpalljet Tona. (كَدَأْبِ آلِ فِرْعَوْنَ وَالَّذِينَ مِن قَبْلِهِمْ كَذَّبُوا بِآيَاتِنَا) 3:11; 8:54
- Dhe i përgëzon besimtarët që bëjnë vepra të mira se kanë shpërblim. (وَيُبَشِّرُ الْمُؤْمِنِينَ الَّذِينَ يَعْمَلُونَ الصَّالِحَاتِ أَنَّ لَهُمْ أَجْرًا) 17:9; 18:2
- Zoti e zgjeron furnizimin kujt do nga robërit e Tij dhe e ngushton. (اللَّهَ يَبْسُطُ الرِّزْقَ لِمَن يَشَاءُ مِنْ عِبَادِهِ وَيَقْدِرُ) 28:82; 29:62
- Dhe do të ktheheni te Njohësi i të padukshmes dhe të dukshmes, e do t'ju lajmërojë për atë që keni bërë. (وَسَتُرَدُّونَ إِلَى عَالِمِ الْغَيْبِ وَالشَّهَادَةِ فَيُنَبِّئُكُم بِمَا كُنتُمْ) 9:105; 62:8
- Dhe të afërmit e gjakut janë më të afërt me njëri-tjetrin në Librin e Zotit. (وَأُولُو الْأَرْحَامِ بَعْضُهُمْ أَوْلَى بِبَعْضٍ فِي كِتَابِ اللَّهِ) 8:75; 33:6
cmds - Commands, Exhortations, Prohibitions, Instructions
- fard / wajib (فرض / واجب) — i detyrueshëm (duhet bërë; mëkat nëse lihet)
- mustahabb / mandub (مستحب / مندوب) — i rekomanduar (shpërblehet nëse bëhet, nuk është mëkat nëse lihet)
- mubah (مباح) — neutral / i lejuar (as shpërblim as mëkat)
- makruh (مكروه) — i urryer (i dekurajuar, por jo mëkat nëse bëhet)
- haram (حرام) — i ndaluar (mëkat të bëhet)
- halal (حلال, i lejuar / i ligjshëm) — përfshin edhe mubah edhe mustahabb — çdo gjë që nuk është e ndaluar
- Adhuro vetëm Allahun dhe kërko ndihmën/assistencën e Tij. 1:5
- Adhuro vetëm Allahun. 2:21
- Mos i shoqëro Allahut asnjë shok. 2:22
- Allahu është Ai që fal (pranon pendimin), Ai e pranoi pendimin e Ademit (paqja qoftë mbi të). 2:37
- Mos e përzieni të vërtetën me gënjeshtrën, dhe mos e fshihni të vërtetën. 2:42
- Kryeni namazin (faljen e përditshme), dhe jepni zeqatin (lëmoshën). 2:43
- Urdhëroni të tjerët për virtyt vetëm pasi ta praktikoni vetë. 2:44
- Kërko ndihmën e Allahut në të gjitha çështjet e tua. 2:45
- Mos u angazhoni në korrupsion dhe mos e përhapni atë. 2:60
- Mos i pengoni njerëzit të shkojnë në shtëpitë e adhurimit. 2:114
- Respektoni shenjtërinë e xhamisë. Mbani vendet tuaja të lutjes të pastra dhe të pastërta. 2:125
- Kujtoni Allahun (duke falur, lavdëruar, etj.) dhe Ai do t'ju kujtojë juve, dhe jini mirënjohës ndaj Tij. 2:152
- Praktikoni durimin në vështirësi. 2:153
- Mos ndiqni gjurmët e Shejtanit (Djallit) i cili është armik i hapur. 2:168
- Mos ndiqni askënd në mënyrë të verbër. 2:170
- Ruani dhe përmbushni të gjitha besimet. Kryeni detyrat tuaja fetare me sinqeritet. Përmbushni betimet dhe marrëveshjet tuaja. Mbani premtimet, veçanërisht ato që i bëni Allahut. Mbështetni ata në nevojë dhe lehtësoni vështirësitë. Shmangni kryerjen e mëkateve që çojnë në humbjen e favors hyjnore. Mos lejoni që krenaria t'ju çojë në padrejtësi. 2:177
- Në kisas (Ligji i Barazisë në ndëshkim) ka jetë për ju. 2:179
- Agjëroni gjatë muajit të Ramazanit. Respektoni agjërimin e caktuar për t'u bërë Muttekun (të devotshmit). 2:183
- Respektoni Kuranin si burimin përfundimtar të udhëzimit. 2:185
- Mos e hani pasurinë e njëri-tjetrit në mënyrë të padrejtë, dhe mos u jepni ryshfet gjyqtarëve (përpara se të paraqisni çështjet tuaja). 2:188
- Mos shtypni të tjerët, qoftë me fjalë apo me vepra. Kurrë mos luftoni si agresor, por vetëm në mbrojtje. 2:190
- Mbroni jetimët. Sa u përket jetimëve, punoni me ndershmëri në pasurinë e tyre dhe mos e përvetësoni pasurinë e tyre. 2:220
- Pendohuni dhe kërkoni faljen e Allahut. Mos kryeni marrëdhënie seksuale gjatë periudhës së menstruacioneve. Ruani pastërtinë dhe pastërtinë (si fizikisht ashtu edhe shpirtërisht). 2:222
- Përmbushni përgjegjësitë tuaja ndaj familjes suaj. 2:233
- Zgjidhni udhëheqësit bazuar në meritat e tyre. 2:247
- Mos ushtroni detyrim në fe. 2:256
- Shpenzoni pasurinë në bamirësi. Jini bamirës si në pasuri ashtu edhe në kohë. 2:261
- Mos e prishni bamirësinë duke u mburrur për bujarinë tuaj. 2:264
- Shejtani (Djalli) ju kërcënon me varfëri dhe ju urdhëron të kryeni vepra të ndyra (vepra të këqija, marrëdhënie seksuale të paligjshme, mëkate). 2:268
- Kërkoni nevojtarët dhe ndihmoni ata. 2:273
- Mos u përfshini me kamatë ose interes. Mos e konsumoni pasurinë me interes. Mos e hani ribanë (kamatën). 2:275
- Jepni më shumë kohë për të shlyer nëse debitori është në vështirësi. 2:280
- Mbani fjalën tuaj në transaksionet tregtare. Jini të sinqertë në çështjet tuaja financiare. Veproni me integritet në të gjitha angazhimet tuaja. Kur të lidhni një borxh për një periudhë të caktuar, shkruajeni atë. Merrni dëshmitarë sa herë që lidhni një kontratë tregtare. 2:282
- Ruani dhe përmbushni të gjitha besimet. 2:283
- Besoni në Librat e zbritur dhe në të gjithë Profetët. 2:285
- Allahu nuk e ngarkon një person përtej aftësisë së tij. Ata marrin shpërblim për të mirat që kanë fituar, dhe ndëshkohen për të këqijat që kanë fituar. Zoti nuk e ngarkon njeriun përtej kapacitetit të tij; as ne nuk duhet ta bëjmë këtë. Besoni në planin e Allahut edhe në vështirësi. 2:286
- Kush i përmbush premtimet dhe i frikësohet shumë Allahut, atëherë Allahu i do ata që janë të devotshëm. 3:76
- Kryeni haxhin (pelegrinazhin) nëse jeni në gjendje. 3:97
- Mos u përçani. 3:103
- Urdhëroni të mirën dhe ndaloni të keqen. Nxitni drejtësinë në komunitetin tuaj. Thirrini të tjerët në përkujtimin e Allahut. 3:104
- Te Allahu duhet të mbështeten besimtarët. 3:122
- Mos e hani ribanë (kamatën). 3:130
- Bindjuni Allahut dhe të Dërguarit të Tij për të marrë mëshirë. 3:132
- Allahu i do ata që shpenzojnë (në çështjen e Allahut – vepra bamirësie, lëmoshë, etj.) në begati dhe në vështirësi, ata që frenojnë zemërimin dhe ata që ua falin njerëzve. 3:134
- Frenoni zemërimin. Kontrolloni zemërimin tuaj. 3:134
- Falni dhe ndjeni gabimet e të tjerëve. 3:135
- Mos u bëni të vrazhdë në fjalim. Jini të durueshëm me ata që ndryshojnë nga ju. 3:159
- Nëse Allahu ju ndihmon, askush nuk mund t'ju mposhtë; dhe nëse Ai ju braktis, kush është pas Tij që mund t'ju ndihmojë? 3:160
- Secili do të shijojë vdekjen. Dhe vetëm në Ditën e Ringjalljes do t'ju paguhet shpërblimi i plotë. 3:185
- Mendoni thellësisht për mrekullitë e natyrës dhe krijimin e këtij universi. Dijeni se Zoti e krijoi universin me kuptim dhe qëllim. 3:191
- Burrat dhe gratë kanë shpërblim të barabartë për veprat e tyre. 3:195
- Për ata që i frikësohen Zotit të tyre, ka kopshte nën të cilët rrjedhin lumenj (në Xhenet); aty do të banojnë përgjithmonë, si mikpritje nga Allahu. 3:198
- Përpiquni gjithmonë për kënaqësinë e Allahut në çdo veprim. 3:200
- Jini të devotshëm ndaj Zotit tuaj, frikësohuni Atij dhe (mos i prisni lidhjet) e farefisnisë (të afërmve). 4:1
- Jepuni jetimëve pasurinë e tyre dhe mos e shkëmbeni (të keqen tuaj) me të mirën e tyre; dhe mos e hani pasurinë e tyre (duke ia shtuar pasurisë tuaj). 4:2
- Jepuni grave (që martoheni) mehrin e tyre (dhuratën e detyrueshme të martesës që burri i jep gruas në kohën e martesës) me zemër të mirë. 4:4
- Ruani të drejtat e jetimëve. 4:6
- Pasuria e të vdekurit duhet të shpërndahet midis anëtarëve të familjes së tij. Gratë kanë të drejtë trashëgimie. 4:7
- Mos e hani pasurinë e jetimëve në mënyrë të padrejtë. 4:10
- Bindjuni urdhërimeve në lidhje me trashëgiminë. 4:11
- Është e ndaluar të trashëgoni gratë kundër vullnetit të tyre, dhe nuk duhet t'i trajtoni ato me ashpërsi. Jetoni me to (gratë) në mënyrë të ndershme. Respektoni dhe respektoni të drejtat e grave. Trajtoni bashkëshortin tuaj me mirësi dhe dhembshuri. Trajtoni gratë me nder dhe drejtësi. 4:19
- Mos martohuni me ata që janë të afërm të gjakut me ju. 4:23
- Mos e vrisni veten (as njëri-tjetrin). Sigurisht, Allahu është Mëshirues ndaj jush. Mos e hani pasurinë e njëri-tjetrit në mënyrë të padrejtë. 4:29
- Nëse shmangni mëkatet e mëdha që janë të ndaluara të bëhen, Allahu do t'ju falë mëkatet (e vogla) tuaja dhe do t'ju futë në një hyrje fisnike (d.m.th. Xhenet). 4:31
- Mos lakmoni ato gjëra me të cilat Allahu ka bërë që disa prej jush t'i kalojnë të tjerët. Shmangni zilinë dhe xhelozinë. 4:32
- Burrat janë mbrojtës dhe mbajtës të grave, sepse Allahu i ka bërë ata të shquar njëri ndaj tjetrit, dhe sepse ata shpenzojnë (për t'i mbajtur ato) nga pasuria e tyre. Burri është mbrojtës dhe mbështetës i familjes. 4:34
- Adhuroni Allahun dhe mos i shoqëroni Atij asnjë shok në adhurim, bëju mirë prindërve, të afërmve, jetimëve, të varfërve, fqinjit, shokut pranë jush, udhëtarit (që takoni) dhe atyre (skllevërve) që zotëroni. Allahut nuk i pëlqejnë ata që janë krenarë dhe mburravecë. Bëju mirë të tjerëve. Trego mëshirë për ata që janë të dobët. Ruani lidhjet familjare dhe nderoni të afërmit. 4:36
- Mos u bëni koprracë. 4:37
- Allahu nuk fal që t'i shoqërohet Atij shok në adhurim, por fal çdo gjë tjetër përveç kësaj, kujt të dojë Ai. 4:48
- Mos i keni zili të tjerët. 4:54
- Allahu ju urdhëron që t'ua ktheni besimet atyre që u përkasin. Kur të gjykoni midis njerëzve, gjykoni me drejtësi. 4:58
- Bindjuni Allahut dhe të Dërguarit të Tij. Respektoni ata që janë në autoritet midis jush. 4:59
- Mos shtypni të dobëtit dhe të prekshmit. 4:75
- Çdo e mirë që ju vjen, është nga Allahu, por çdo e keqe që ju godet, është nga vetvetja juaj. 4:79
- Ai që i bindet të Dërguarit (Muhammedit ﷺ), i është bindur Allahut. 4:80
- Kushdo që ndërmjetëson për një qëllim të mirë, do të ketë shpërblimin e tij, dhe kushdo që ndërmjetëson për një qëllim të keq, do të ketë pjesën e tij në barrën e tij. 4:85
- Nuk është e drejtë për një besimtar të vrasë një besimtar, përveçse gabimisht. 4:92
- Kush vret një besimtar me qëllim, shpërblimi i tij është Xhehennemi, ku do të banojë përgjithmonë. Zemërimi dhe Mallkimi i Allahut janë mbi të, dhe një ndëshkim i madh është përgatitur për të. 4:93
- Ai që emigron (nga shtëpia e tij) në rrugën e Allahut, do të gjejë në tokë shumë vendbanime dhe shumë për të jetuar. 4:100
- Jini të përpiktë në faljet tuaja. 4:103
- Mos mbështetni dhe mos jini avokat për ata që tradhtojnë besimet e tyre. 4:105
- Kërkoni Faljen e Allahut, sigurisht, Allahu është Falës dhe Mëshirues. 4:106
- O ju që besoni! Qëndroni me vendosmëri për drejtësinë, si dëshmitarë të Allahut, edhe nëse është kundër vetvetes suaj, ose prindërve tuaj, ose të afërmve tuaj, qoftë ai i pasur apo i varfër. Mos e vononi drejtësinë; veproni menjëherë për të korrigjuar të gabuarat. 4:135
- Hipokritët kërkojnë të mashtrojnë Allahun, por Ai i mashtron ata. 4:142
- Hipokritët do të jenë në fundin më të ulët (e shkallës) të Zjarrit; dhe nuk do të gjeni ndihmës për ta. 4:145
- Allahut nuk i pëlqen që e keqja të shprehet publikisht, përveç atij që është dëmtuar. 4:148
- Të Dërguarit si përcjellës të lajmit të mirë dhe si paralajmërues, në mënyrë që njerëzit të mos kenë arsye kundër Allahut pas (ardhjes së) të Dërguarve. 4:165
- Përmbushni kontratat dhe premtimet tuaja. 5:1
- Mbështetni njëri-tjetrin në virtyt dhe devotshmëri, jo në mëkat dhe armiqësi. 5:2
- Mos konsumoni kafshë të ngordhura, gjakun e kafshëve ose mish derri. 5:3
- Bëni drejtësi, dhe mos lejoni që armiqësia dhe urrejtja ndaj të tjerëve t'ju bëjë të shmangni drejtësinë. Jini të drejtë dhe të ndershëm në marrëdhëniet tuaja. Dijeni se të qenit i drejtë është afër devotshmërisë. Mos e vononi drejtësinë; veproni menjëherë për të korrigjuar të gabuarat. 5:8
- Kërkoni mjetet për t'iu afruar Allahut dhe përpiquni në rrugën e Tij sa më shumë që të mundeni. Në mënyrë që të jeni të suksesshëm. 5:35
- Përmbushni betimet dhe premtimet tuaja. 5:89
- Shmangni pijet dehëse dhe alkoolin. Shmangni rreptësisht dehëset (të gjitha llojet e pijeve alkoolike), bixhozin, gurët e altarëve (Al-Ansab) dhe shigjetat (për kërkim të fatit) të cilat janë të gjitha vepra të ndyra të Shejtanit. 5:90
- Mos vritni gjah ndërsa jeni në gjendje ihrami për haxh ose umre. 5:95
- Mos pyetni për gjëra që, nëse do t'ju bëheshin të qarta, mund t'ju shkaktonin vështirësi. 5:101
- Mos i fyesni zotat e të tjerëve. Mos i fyesni ata që (jobesimtarët) adhurojnë përveç Allahut, sepse ata do të fyejnë Allahun pa dije. 6:108
- Nëse i bindeni shumicës së atyre që janë në tokë, ata do t'ju devijojnë larg rrugës së Allahut. Ata ndjekin vetëm hamendje dhe ata vetëm gënjejnë. 6:116
- Largohuni (o njerëz, nga të gjitha llojet e) mëkateve, të hapura dhe të fshehta. 6:120
- Mos hani (o besimtarë) nga ajo (mish) mbi të cilën nuk është përmendur emri i Allahut (në kohën e therjes së kafshës). 6:121
- Këdo që Allahu do ta udhëzojë, ia hap gjoksin për Islam, dhe këdo që do ta lërë të humbur, ia bën gjoksin të ngushtë dhe të shtrënguar. 6:125
- Jini të matur në shpenzime dhe shmangni ekstravagancën. Ruani të drejtat e të gjitha krijesave. 6:141
- Mos i shoqëroni asgjë në adhurim Allahut, bëju mirë dhe të devotshëm prindërve, mos i vrisni fëmijët tuaj nga frika e varfërisë, mos iu afroni veprave të turpshme, mos vrisni askënd që Allahu e ka ndaluar, përveçse për një shkak të drejtë. 6:151
- Jini të ndershëm; mos mashtroni në asnjë nga marrëveshjet tuaja. Mos iu afroni pasurisë së jetimit, përveçse për ta përmirësuar atë, jepni masën dhe peshën e plotë me drejtësi, sa herë që jepni fjalën tuaj, thoni të vërtetën edhe nëse ka të bëjë me një të afërm, dhe përmbushni Besëlidhjen e Allahut. 6:152
- Ndiqni Rrugën e Drejtë dhe mos ndiqni rrugë të tjera, sepse ato do t'ju ndajnë nga Rruga e Tij. 6:153
- Thuaj (o Muhamed ﷺ): "Vërtet, falja ime, kurbanimi im, jeta ime dhe vdekja ime janë për Allahun, Zot të gjithësisë." 6:162
- Mos u bëni mendjemëdhenj. 7:13
- Mos lejoni që Shejtani (Djalli) t'ju mashtrojë. 7:27
- Thuaj (o Muhamed ﷺ): Zoti im ka urdhëruar drejtësinë… 7:29
- Qëndroni brenda kufijve të vendosur nga Allahu në të gjitha çështjet. Shmangni tejkalimin e kufirit në fjalim dhe vepra. Hani dhe pini por mos e teproni. Vishni rroba të mira gjatë kohës së faljes. 7:31
- Allahu krijoi qiejt dhe tokën në gjashtë Ditë, dhe më pas u vendos mbi Fron (në mënyrën që i përshtatet Madhërisë së Tij). 7:54
- Thirreni Zotin tuaj me përulësi dhe fshehtas. Ai nuk i do ata që tejkalojnë kufirin. 7:55
- Dhe mos bëni çrregullim në tokë, pasi ajo është vënë në rregull, dhe thirreni Atë me frikë dhe shpresë. 7:56
- Por ata që bënë vepra të këqija dhe më pas u penduan dhe besuan, vërtet, Zoti juaj pas (gjithë) kësaj është Falës dhe Mëshirues. 7:153
- Thuaj (o Muhamed ﷺ): "O njerëz! Unë jam dërguar te të gjithë ju si i Dërguar i Allahut…" 7:158
- Dhe (të gjithë) Emrat më të Bukur i përkasin Allahut, prandaj thirreni Atë me to, dhe lini ata që i mohojnë Emrat e Tij… 7:180
- Këdo që Allahu e lë të humbur, askush nuk mund ta udhëzojë; dhe Ai i lë ata të enden verbërisht në tejkalimet e tyre. 7:186
- Trego falje, urdhëro të mirën dhe largohu nga të paditurit (d.m.th. mos i ndëshko ata). 7:199
- Falni të tjerët për gabimet e tyre. 7:199
- Dhe nëse ndonjë nxitje e keqe të vjen nga Shejtani (Djalli), atëherë kërko strehim te Allahu. Vërtet, Ai është Gjithëdëgjues, Gjithëdijshëm. 7:200
- Besimtarët janë vetëm ata që, kur përmendet Allahu, ndiejnë frikë në zemrat e tyre dhe kur u lexohen ajetet e Tij, ato (ajetet) ua shtojnë besimin… 8:2
- Mos e tradhtoni Allahun dhe të Dërguarin e Tij, dhe mos e tradhtoni me dije besimin tuaj (dhe gjithë detyrat që Allahu ju ka urdhëruar). 8:27
- Nëse i bindeni dhe i frikësoheni Allahut, Ai do t'ju japë një Furkan (masë për të gjykuar midis së vërtetës dhe gënjeshtrës, ose një rrugëdalje nga çdo vështirësi). 8:29
- Ata që nuk besojnë e shpenzojnë pasurinë e tyre për të penguar (njerëzit) nga rruga e Allahut, dhe kështu do të vazhdojnë ta shpenzojnë; por në fund ajo do të bëhet pikëllim për ta. 8:36
- Thuaju atyre që nuk besuan, nëse pushojnë (nga mosbesimi), do t'u falet e kaluara. Por nëse kthehen (përsëri), atëherë shembujt e atyre (të ndëshkuarve) para tyre tashmë kanë kaluar (si paralajmërim). 8:38
- Kur të përballeni me (një forcë armike), qëndroni të vendosur dhe përmendeni shumë emrin e Allahut (me gjuhë dhe mendje), në mënyrë që të jeni të suksesshëm. 8:45
- Mos u bëni si ata që dolën nga shtëpitë e tyre me mendjemadhësi dhe për t'u parë nga njerëzit, dhe që pengojnë (njerëzit) nga rruga e Allahut. 8:47
- Allahu nuk e ndryshon kurrë një dhunti që i ka dhënë një populli, derisa ata të ndryshojnë atë që është në vetveten e tyre. 8:53
- Krijesat më të këqija para Allahut janë ata që nuk besojnë. 8:55
- Zoti vendos dashuri dhe afeksion midis zemrave të atyre që besojnë në Të. 8:63
- Mbroni dhe ndihmoni ata që kërkojnë mbrojtje. 9:6
- Nuk është e drejtë për idhujtarët të mirëmbajnë xhamitë e Allahut. 9:17
- Ata (jobesimtarët, çifutët dhe të krishterët) duan ta shuajnë dritën e Allahut (me të cilën u dërgua Muhamedi ﷺ – Teuhidi Islamik) me gojët e tyre, por Allahu nuk do të lejojë përveçse të përsosë dritën e Tij, edhe pse jobesimtarët e urrejnë atë. 9:32
- Sadakatë (d.m.th. Zekati) janë vetëm për: 1) të varfërit, 2) nevojtarët, 3) ata që janë punësuar për të mbledhur fondet, 4) për të tërhequr zemrat e atyre që janë prirë drejt Islamit, 5) për të liruar të burgosurit, 6) për ata që janë në borxh, 7) për çështjen e Allahut (d.m.th. për luftëtarët), dhe 8) për udhëtarin. 9:60
- Kushdo që kundërshton dhe tregon armiqësi ndaj Allahut dhe të Dërguarit të Tij (ﷺ), sigurisht që për të do të jetë Zjarri i Xhehennemit ku do të banojë përgjithmonë. Ai është poshtërim i skajshëm. 9:63
- Hipokritët, burra dhe gra, janë njësoj. Ata e kanë harruar Allahun, kështu që Ai i ka harruar ata. 9:67
- Përpiquni për pastërti. Respektoni shenjtërinë e xhamisë. 9:108
- Nuk është e drejtë (për Profetin dhe ata që besojnë) të kërkojnë falje nga Allahu për idhujtarët, edhe nëse janë të afërm, pasi u bë e qartë se ata janë banorë të Zjarrit (sepse vdiqën në gjendje mosbesimi). 9:113
- Kush është më i padrejtë se ai që shpif gënjeshtër kundër Allahut ose i mohon ajetet e Tij? Sigurisht, mëkatarët nuk do të kenë kurrë sukses! 10:17
- Ata adhurojnë përveç Allahut gjëra që nuk i dëmtojnë dhe as nuk u bëjnë dobi, dhe thonë: "Këta janë ndërmjetësuesit tanë te Allahu." Thuaju: "A po i tregoni Allahut diçka që Ai nuk e di në qiej dhe në tokë?" Qoftë lavdëruar dhe lartësuar Ai mbi gjithçka që ata i shoqërojnë si shokë! 10:18
- Shpërblimi i një vepre të keqe është i ngjashëm me të. 10:27
- I tillë është Allahu, Zoti juaj i vërtetë. Pra, pas së vërtetës, çfarë tjetër mund të ketë përveç humbjes? Si pra po largoheni? 10:32
- Shumica e tyre ndjekin vetëm hamendje. Sigurisht, hamendja nuk mund të zëvendësojë të vërtetën. 10:36
- Vërtet! Allahu nuk u bën padrejtësi njerëzve në asgjë; por njerëzit i bëjnë padrejtësi vetes së tyre. 10:44
- Dijeni se dhuntia e Allahut është më e mirë se çdo gjë që njeriu mund të grumbullojë ose të grumbullojë. 10:58
